const request = require('request');

const options = {
  method: 'GET',
  url: 'http://localhost:8080/rest/v2.0/companies/1234/projects/1234/assets/asset_types',
  qs: {
    asset_type_ids: 'SOME_STRING_VALUE',
    include_asset_counts: 'SOME_BOOLEAN_VALUE',
    is_asset: 'SOME_BOOLEAN_VALUE',
    eligible_sub_asset_of: 'SOME_STRING_VALUE',
    sort: 'SOME_STRING_VALUE'
  },
  headers: {
    'Procore-Company-Id': 'SOME_INTEGER_VALUE',
    'Accept-Language': 'SOME_STRING_VALUE'
  }
};

request(options, function (error, response, body) {
  if (error) throw new Error(error);

  console.log(body);
});

var client = new HttpClient();
var request = new HttpRequestMessage
{
    Method = HttpMethod.Get,
    RequestUri = new Uri("http://localhost:8080/rest/v2.0/companies/1234/projects/1234/assets/asset_types?asset_type_ids=SOME_STRING_VALUE&include_asset_counts=SOME_BOOLEAN_VALUE&is_asset=SOME_BOOLEAN_VALUE&eligible_sub_asset_of=SOME_STRING_VALUE&sort=SOME_STRING_VALUE"),
    Headers =
    {
        { "Procore-Company-Id", "SOME_INTEGER_VALUE" },
        { "Accept-Language", "SOME_STRING_VALUE" },
    },
};
using (var response = await client.SendAsync(request))
{
    response.EnsureSuccessStatusCode();
    var body = await response.Content.ReadAsStringAsync();
    Console.WriteLine(body);
}
